create table if not exists property_rates (id bigserial primary key, nightly_rate numeric(12,2) not null, currency text not null default 'LKR', active boolean not null default true, created_at timestamptz not null default now());
create table if not exists seasonal_rates (id bigserial primary key, name text not null, start_date date not null, end_date date not null, nightly_rate numeric(12,2) not null, active boolean not null default true, check (end_date > start_date));
create table if not exists special_offers (id bigserial primary key, name text not null, discount_percent numeric(5,2) not null, start_date date not null, end_date date not null, active boolean not null default true, check (end_date > start_date));
create table if not exists long_stay_discounts (id bigserial primary key, min_nights integer not null unique check (min_nights > 0), discount_percent numeric(5,2) not null, active boolean not null default true);
insert into property_rates (nightly_rate) select 45000 where not exists (select 1 from property_rates);
insert into seasonal_rates (name,start_date,end_date,nightly_rate,active) select * from (values ('Peak Season',date '2026-12-20',date '2027-01-11',55000,true),('April Holidays',date '2027-04-10',date '2027-04-19',50000,true),('Annual Festival',date '2027-08-01',date '2027-08-06',52000,false)) v(name,start_date,end_date,nightly_rate,active) where not exists (select 1 from seasonal_rates);
insert into special_offers (name,discount_percent,start_date,end_date,active) select * from (values ('Highlands Escape Deal',15,date '2026-11-01',date '2026-12-01',true),('Long Stay Retreat',20,date '2026-12-01',date '2027-04-01',true)) v(name,discount_percent,start_date,end_date,active) where not exists (select 1 from special_offers);
insert into long_stay_discounts (min_nights,discount_percent,active) select * from (values (7,10,true),(14,15,true)) v(min_nights,discount_percent,active) where not exists (select 1 from long_stay_discounts);
